  margin-bottom:12px;
  flex-wrap:wrap;
}

.weekly-calendar{
  display:grid;
  grid-template-columns:repeat(7,minmax(150px,1fr));
  gap:12px;
  width:100%;
}

.weekly-day{
  min-height:260px;
  background:#ffffff;
  border:1px solid #dbe5ef;
  border-radius:16px;
  padding:12px;
  cursor:pointer;
}

.weekly-day.today{
  border:2px solid #B91C1C;
  background:#fff7f7;
}

.weekly-day-head{
  display:flex;
  justify-content:space-between;
  align-items:center;
  margin-bottom:12px;
  padding-bottom:8px;
  border-bottom:1px solid #e2e8f0;
}

.weekly-day-head strong{
  color:#123B63;
  font-size:16px;
}

.weekly-day-head span{
  font-weight:800;
  color:#64748B;
}

.weekly-visit{
  background:#f8fafc;
  border:1px solid #e2e8f0;
  border-left:5px solid #1E5A8A;
  border-radius:12px;
  padding:10px;
  margin-bottom:8px;
  cursor:pointer;
}

.weekly-visit strong{
  display:block;
  font-size:14px;
  color:#0f172a;
  margin-bottom:4px;
}

.weekly-visit span{
  display:block;
  font-size:13px;
  color:#475569;
}

.waze-link{
  display:inline-block;
  margin-top:8px;
  padding:8px 12px;
  background:#33ccff;
  color:#06364a;
  font-weight:800;
  border-radius:10px;
  text-decoration:none;
}

.waze-link:hover{
  opacity:.85;
}

.toast-stack{
  position:fixed;
  top:18px;
  right:18px;
  z-index:3000;
  display:flex;
  flex-direction:column;
  gap:10px;
  max-width:360px;
}

.toast-card{
  background:#ffffff;
  border-left:6px solid #B91C1C;
  border-radius:14px;
  box-shadow:0 12px 32px rgba(0,0,0,.18);
  padding:14px 42px 14px 14px;
  position:relative;
}

.toast-card strong{
  display:block;
  color:#123B63;
  margin-bottom:4px;
}

.toast-card p{
  margin:0;
  color:#334155;
  font-size:13px;
}

.toast-close{
  position:absolute;
  top:8px;
  right:10px;
  border:0;
  background:transparent;
  font-size:22px;
  line-height:1;
  cursor:pointer;
  color:#64748b;
}

@media(max-width:900px){
  .weekly-calendar{
    grid-template-columns:1fr;
  }
