  max-height:52vh;
  padding:10px;
}

.notification-item{
  padding:10px;
  border-radius:12px;
  margin-bottom:8px;
  border:1px solid #e2e8f0;
}

.notification-item.unread{
  background:#fff7ed;
  border-left:5px solid #B91C1C;
}

.notification-item.read{
  background:#f8fafc;
}

.notification-item strong{
  display:block;
  color:#123B63;
  margin-bottom:3px;
}

.notification-item p{
  margin:0 0 4px;
  font-size:13px;
  color:#334155;
}

.home-layout{
  display:grid;
  grid-template-columns:minmax(0,1fr) 360px;
  gap:16px;
  align-items:start;
}

.home-sidebar{
  display:flex;
  flex-direction:column;
  gap:16px;
}

.contrato-list{
  display:flex;
  flex-direction:column;
  gap:8px;
}

.contrato-item{
  border:1px solid #e2e8f0;
  border-left:5px solid #15803D;
  border-radius:12px;
  padding:10px;
  background:#f8fafc;
}

.contrato-item strong{
  display:block;
  color:#123B63;
  font-size:16px;
}

.contrato-item span{
  color:#475569;
  font-size:13px;
}

.alerta-fotos{
  grid-column:1/-1;
  background:#fff7ed;
  border:1px solid #fed7aa;
  color:#9a3412;
  border-radius:10px;
  padding:10px;
  font-size:13px;
  font-weight:700;
}

@media(max-width:1000px){
  .home-layout{
    grid-template-columns:1fr;
  }

  .notifications-panel{
    left:12px;
    right:12px;
    top:70px;
    width:auto;
  }
}



/* Ajustes v1.8.0 — senha, captador e log */
.password-box{
  background:#f8fafc;
  border:1px solid #dbe5ef;
  border-radius:14px;
  padding:16px;
  margin-bottom:16px;
}

.password-box h3{
  margin:0 0 12px;
  color:#123B63;
}

.password-row{
  display:flex;
  gap:10px;
  flex-wrap:wrap;
}

.password-row input{
  flex:1;
  min-width:220px;
}

.hint{
  color:#64748b;
  font-size:13px;
}


/* Ajustes v1.9.0 — painel administrador e visualização somente leitura */
.permissions-box{
  background:#f8fafc;
  border:1px solid #dbe5ef;
  border-radius:14px;
  padding:14px;
  margin-top:14px;
}

.permissions-box h3{
  margin:0 0 6px;
  color:#123B63;
}

.perm-row{
  display:flex;
  align-items:center;
  justify-content:space-between;
  gap:12px;
  padding:10px 0;
  border-bottom:1px solid #e2e8f0;
}

.perm-row:last-child{
  border-bottom:0;
}

.perm-row span{
  font-weight:700;
  color:#334155;
}

.toggle{
  min-width:62px;
  border:0;
  border-radius:999px;
  padding:7px 12px;
  font-weight:900;
  cursor:pointer;
}

.toggle.on{
  background:#dcfce7;
  color:#166534;
}

.toggle.off{
  background:#fee2e2;
  color:#991b1b;
}


/* Ajustes v1.9.1 */
.admin-help{
  background:#eff6ff;
  border:1px solid #bfdbfe;
  color:#123B63;
  border-radius:14px;
  padding:12px 14px;
  margin-bottom:14px;
}

.admin-help strong{
  display:block;
  margin-bottom:4px;
}

.admin-help p{
  margin:0;
  font-size:13px;
}


/* Ajustes v1.9.2 */
.permissions-box{
  margin-top:18px;
}

/* Ajustes v2.0.0 — agenda, canceladas, filtros e destaque de fotos */
.foto-destaque{outline:2px solid #f59e0b;box-shadow:0 0 0 2px rgba(245,158,11,.25);}
.foto-destaque::after{content:" 📸";}
.foto-destaque-card{background:#fff7ed!important;border-color:#fed7aa!important;}
.reportbar label{display:flex;flex-direction:column;gap:4px;font-weight:800;color:#123B63;}
.reportbar label span{font-size:12px;}


/* Ajustes v2.0.1 — Canceladas e edição mostrador */
.tabs button.active{
  cursor:pointer;
}

.status.cancelada{
  background:#fee2e2;
  color:#991b1b;
}

.visitcard.cancelada{
  opacity:.92;
}


/* Ajustes v2.1.0 — dashboard gerencial filtrável */
.dashboard-filters{
  display:flex;
  gap:10px;
  flex-wrap:wrap;
  align-items:end;
}

.dashboard-filters label{
  display:flex;
  flex-direction:column;
  gap:4px;
  font-weight:800;
  color:#123B63;
}

.dashboard-filters label span{
  font-size:12px;
}

.dashboard-filters input,
.dashboard-filters select{
  min-height:42px;
}

.dashboard-kpis{
  display:grid;
  grid-template-columns:repeat(4,minmax(160px,1fr));
  gap:14px;
  margin-bottom:16px;
}

@media(max-width:900px){
  .dashboard-kpis{
    grid-template-columns:1fr 1fr;
  }
}

@media(max-width:560px){
  .dashboard-kpis{
    grid-template-columns:1fr;
  }
}

