/* Ajustes v1.5.0 — calendário semanal e pop-up */
.calendar-mode-bar{
  display:flex;
  gap:8px;
  margin-bottom:12px;
  flex-wrap:wrap;
}

.weekly-calendar{
  display:grid;
  grid-template-columns:repeat(7,minmax(150px,1fr));
  gap:12px;
  width:100%;
}

.weekly-day{
  min-height:260px;
  background:#ffffff;
  border:1px solid #dbe5ef;
  border-radius:16px;
  padding:12px;
  cursor:pointer;
}

.weekly-day.today{
  border:2px solid #B91C1C;
  background:#fff7f7;
}

.weekly-day-head{
  display:flex;
  justify-content:space-between;
  align-items:center;
  margin-bottom:12px;
  padding-bottom:8px;
  border-bottom:1px solid #e2e8f0;
}

.weekly-day-head strong{
  color:#123B63;
  font-size:16px;
}

.weekly-day-head span{
  font-weight:800;
  color:#64748B;
}

.weekly-visit{
  background:#f8fafc;
  border:1px solid #e2e8f0;
  border-left:5px solid #1E5A8A;
  border-radius:12px;
  padding:10px;
  margin-bottom:8px;
  cursor:pointer;
}

.weekly-visit strong{
  display:block;
  font-size:14px;
  color:#0f172a;
  margin-bottom:4px;
}

.weekly-visit span{
  display:block;
  font-size:13px;
  color:#475569;
}

.waze-link{
  display:inline-block;
  margin-top:8px;
  padding:8px 12px;
  background:#33ccff;
  color:#06364a;
  font-weight:800;
  border-radius:10px;
  text-decoration:none;
}

.waze-link:hover{
  opacity:.85;
}

.toast-stack{
  position:fixed;
  top:18px;
  right:18px;
  z-index:3000;
  display:flex;
  flex-direction:column;
  gap:10px;
  max-width:360px;
}

.toast-card{
  background:#ffffff;
  border-left:6px solid #B91C1C;
  border-radius:14px;
  box-shadow:0 12px 32px rgba(0,0,0,.18);
  padding:14px 42px 14px 14px;
  position:relative;
}

.toast-card strong{
  display:block;
  color:#123B63;
  margin-bottom:4px;
}

.toast-card p{
  margin:0;
  color:#334155;
  font-size:13px;
}

.toast-close{
  position:absolute;
  top:8px;
  right:10px;
  border:0;
  background:transparent;
  font-size:22px;
  line-height:1;
  cursor:pointer;
  color:#64748b;
}

@media(max-width:900px){
  .weekly-calendar{
    grid-template-columns:1fr;
  }
  .weekly-day{
    min-height:auto;
  }
  .toast-stack{
    left:12px;
    right:12px;
    top:12px;
    max-width:none;
  }
}

/* Ajustes v1.6.0 — Hoje diário, minha agenda e atualizar fotos */
.daily-calendar{width:100%;}
.daily-day{background:#ffffff;border:2px solid #B91C1C;border-radius:18px;padding:16px;min-height:280px;}
.daily-visit small{display:block;color:#64748b;margin-top:4px;}
.check input{margin-right:8px;}
.status.pos_ok{background:#ECFDF5;color:#047857;}


/* Ajustes v1.7.0 */
.notif-button{
  border:0;
  cursor:pointer;
}

.notifications-panel{
  position:fixed;
  top:78px;
  right:18px;
  z-index:2800;
  width:360px;
  max-height:70vh;
  background:#fff;
  border-radius:18px;
  box-shadow:0 18px 45px rgba(0,0,0,.22);
  border:1px solid #e2e8f0;
  overflow:hidden;
}

.notifications-head{
  display:flex;
  justify-content:space-between;
  align-items:center;
  padding:14px 16px;
  background:#123B63;
  color:#fff;
}

.notifications-head button{
  border:0;
  background:transparent;
  color:#fff;
  font-size:24px;
  cursor:pointer;
}

.notifications-actions{
  padding:10px;
  border-bottom:1px solid #e2e8f0;
}

.notifications-list{
  overflow:auto;
  max-height:52vh;
  padding:10px;
}

.notification-item{
  padding:10px;
  border-radius:12px;
  margin-bottom:8px;
  border:1px solid #e2e8f0;
}

.notification-item.unread{
  background:#fff7ed;
  border-left:5px solid #B91C1C;
}

.notification-item.read{
  background:#f8fafc;
}

.notification-item strong{
  display:block;
  color:#123B63;
  margin-bottom:3px;
}

.notification-item p{
  margin:0 0 4px;
  font-size:13px;
  color:#334155;
}

.home-layout{
  display:grid;
  grid-template-columns:minmax(0,1fr) 360px;
  gap:16px;
  align-items:start;
}

.home-sidebar{
  display:flex;
  flex-direction:column;
  gap:16px;
}

.contrato-list{
  display:flex;
  flex-direction:column;
  gap:8px;
}

.contrato-item{
  border:1px solid #e2e8f0;
  border-left:5px solid #15803D;
  border-radius:12px;
  padding:10px;
  background:#f8fafc;
}

.contrato-item strong{
  display:block;
  color:#123B63;
  font-size:16px;
}

.contrato-item span{
  color:#475569;
  font-size:13px;
}

.alerta-fotos{
  grid-column:1/-1;
  background:#fff7ed;
  border:1px solid #fed7aa;
  color:#9a3412;
  border-radius:10px;
  padding:10px;
  font-size:13px;
  font-weight:700;
}

@media(max-width:1000px){
  .home-layout{
    grid-template-columns:1fr;
  }

  .notifications-panel{
    left:12px;
    right:12px;
    top:70px;
    width:auto;
  }
}



