  border:1px solid #e5e7eb;
  border-radius:16px;
  padding:16px;
  box-shadow:0 8px 20px rgba(15,23,42,.06);
}

.chart-card h3{
  margin:0 0 12px;
  color:#123B63;
}

.pie-wrap{
  display:flex;
  align-items:center;
  gap:18px;
  flex-wrap:wrap;
}

.pie{
  width:180px;
  height:180px;
  border-radius:50%;
  border:8px solid #f8fafc;
  box-shadow:inset 0 0 0 1px rgba(15,23,42,.08);
}

.pie-legend{
  flex:1;
  min-width:180px;
}

.legend-row{
  display:grid;
  grid-template-columns:14px 1fr auto;
  gap:8px;
  align-items:center;
  padding:5px 0;
  font-size:13px;
}

.legend-dot{
  width:12px;
  height:12px;
  border-radius:999px;
}

.conversion-grid{
  display:grid;
  grid-template-columns:repeat(auto-fit,minmax(190px,1fr));
  gap:12px;
  margin:12px 0 18px;
}

.conversion-card{
  border:1px solid #e5e7eb;
  border-radius:14px;
  padding:14px;
  background:#f8fafc;
}

.conversion-card span{
  display:block;
  font-size:13px;
  color:#475569;
  font-weight:800;
}

.conversion-card strong{
  display:block;
  font-size:26px;
  color:#123B63;
  margin:4px 0;
}

.conversion-card small{
  color:#64748b;
}

.funnel-report{
  display:flex;
  flex-direction:column;
  gap:10px;
  margin:12px 0 18px;
}

.funnel-row{
  display:grid;
  grid-template-columns:160px 1fr 70px;
  gap:10px;
  align-items:center;
}

.funnel-row span{
  font-weight:800;
  color:#123B63;
}

.funnel-bar{
  height:22px;
  border-radius:999px;
  background:#e5e7eb;
  overflow:hidden;
}

.funnel-bar i{
  display:block;
  height:100%;
  background:#123B63;
  border-radius:999px;
}

.funnel-row strong{
  text-align:right;
}

@media(max-width:700px){
  .funnel-row{
    grid-template-columns:1fr;
  }

  .funnel-row strong{
    text-align:left;
  }
}
/* Ajustes v1.5.0 — calendário semanal e pop-up */
.calendar-mode-bar{
  display:flex;
  gap:8px;
  margin-bottom:12px;
  flex-wrap:wrap;
}

.weekly-calendar{
  display:grid;
  grid-template-columns:repeat(7,minmax(150px,1fr));
  gap:12px;
  width:100%;
}

.weekly-day{
  min-height:260px;
  background:#ffffff;
  border:1px solid #dbe5ef;
  border-radius:16px;
  padding:12px;
  cursor:pointer;
}

.weekly-day.today{
  border:2px solid #B91C1C;
  background:#fff7f7;
}

.weekly-day-head{
  display:flex;
  justify-content:space-between;
  align-items:center;
  margin-bottom:12px;
  padding-bottom:8px;
  border-bottom:1px solid #e2e8f0;
}

.weekly-day-head strong{
  color:#123B63;
  font-size:16px;
}

.weekly-day-head span{
  font-weight:800;
  color:#64748B;
}

.weekly-visit{
  background:#f8fafc;
  border:1px solid #e2e8f0;
  border-left:5px solid #1E5A8A;
  border-radius:12px;
  padding:10px;
  margin-bottom:8px;
  cursor:pointer;
}

.weekly-visit strong{
  display:block;
  font-size:14px;
  color:#0f172a;
  margin-bottom:4px;
}

.weekly-visit span{
  display:block;
  font-size:13px;
  color:#475569;
}

.waze-link{
  display:inline-block;
  margin-top:8px;
  padding:8px 12px;
  background:#33ccff;
  color:#06364a;
  font-weight:800;
  border-radius:10px;
  text-decoration:none;
}

.waze-link:hover{
  opacity:.85;
}

.toast-stack{
  position:fixed;
  top:18px;
  right:18px;
  z-index:3000;
  display:flex;
  flex-direction:column;
  gap:10px;
  max-width:360px;
}

.toast-card{
  background:#ffffff;
  border-left:6px solid #B91C1C;
  border-radius:14px;
  box-shadow:0 12px 32px rgba(0,0,0,.18);
  padding:14px 42px 14px 14px;
  position:relative;
}

.toast-card strong{
  display:block;
  color:#123B63;
  margin-bottom:4px;
}

.toast-card p{
  margin:0;
  color:#334155;
  font-size:13px;
}

.toast-close{
  position:absolute;
  top:8px;
  right:10px;
  border:0;
  background:transparent;
  font-size:22px;
  line-height:1;
  cursor:pointer;
  color:#64748b;
}

@media(max-width:900px){
  .weekly-calendar{
    grid-template-columns:1fr;
  }
  .weekly-day{
    min-height:auto;
  }
  .toast-stack{
    left:12px;
    right:12px;
    top:12px;
    max-width:none;
  }
}

