/* v3.0.6 — calendário com cores por usuário, cliente e balão visual */
.calendar,
.day,
.weekly-calendar,
.weekly-day{
  overflow:visible;
}

.chip,
.weekly-visit,
.daily-visit{
  position:relative;
}

.chip{
  display:flex;
  flex-direction:column;
  gap:1px;
  padding:4px 7px;
  line-height:1.15;
  min-height:28px;
}

.chip strong{
  font-size:11px;
  color:#fff;
  white-space:nowrap;
  overflow:hidden;
  text-overflow:ellipsis;
}

.chip span{
  font-size:10px;
  color:#fff;
  opacity:.95;
  white-space:nowrap;
  overflow:hidden;
  text-overflow:ellipsis;
}

.chip[data-tooltip]:hover::after,
.weekly-visit[data-tooltip]:hover::after,
.daily-visit[data-tooltip]:hover::after{
  content:attr(data-tooltip);
  position:absolute;
  left:0;
  bottom:calc(100% + 10px);
  z-index:9999;
  width:300px;
  max-width:70vw;
  white-space:pre-line;
  background:#0f172a;
  color:#fff;
  border-radius:14px;
  padding:12px 14px;
  font-size:13px;
  line-height:1.45;
  font-weight:700;
  box-shadow:0 18px 35px rgba(15,23,42,.35);
  pointer-events:none;
}

.chip[data-tooltip]:hover::before,
.weekly-visit[data-tooltip]:hover::before,
.daily-visit[data-tooltip]:hover::before{
  content:"";
  position:absolute;
  left:18px;
  bottom:calc(100% + 4px);
  z-index:10000;
  border:7px solid transparent;
  border-top-color:#0f172a;
  pointer-events:none;
}

@media(max-width:700px){
  .chip[data-tooltip]:hover::after,
  .weekly-visit[data-tooltip]:hover::after,
  .daily-visit[data-tooltip]:hover::after{
    width:240px;
    max-width:82vw;
  }
}


