  text-align:center;
  font-weight:900;
  color:#123B63;
}

.month-scheduler-grid{
  display:grid;
  grid-template-columns:repeat(7,minmax(190px,1fr));
  min-width:1330px;
}

.month-day{
  min-height:390px;
  border-right:1px solid #dbe5ef;
  border-bottom:1px solid #dbe5ef;
  position:relative;
  background:#fff;
  cursor:pointer;
}

.month-day.emptyday{
  background:#f8fafc;
}

.month-day-number{
  position:absolute;
  top:8px;
  left:8px;
  z-index:4;
  font-weight:900;
  color:#0f172a;
  font-size:16px;
}

.month-day-hours{
  position:absolute;
  left:0;
  right:0;
  top:34px;
  height:330px;
}

.month-hour-line{
  height:30px;
  border-top:1px solid #f1f5f9;
  position:relative;
}

.month-hour-line span{
  position:absolute;
  right:6px;
  top:2px;
  color:#94a3b8;
  font-size:9px;
  font-weight:800;
}

.month-event{
  position:absolute;
  left:8px;
  right:8px;
  z-index:5;
  border-radius:9px;
  padding:4px 6px;
  color:#fff;
  overflow:hidden;
  box-shadow:0 4px 10px rgba(15,23,42,.14);
  border:1px solid rgba(255,255,255,.25);
}

.month-event strong{
  display:block;
  font-size:11px;
  line-height:1.15;
  white-space:nowrap;
  overflow:hidden;
  text-overflow:ellipsis;
}

.month-event span{
  display:block;
  font-size:10px;
  line-height:1.15;
  white-space:nowrap;
  overflow:hidden;
  text-overflow:ellipsis;
}

.calendar-tooltip-floating{
  white-space:pre-line !important;
  line-height:1.55 !important;
}


