/* v3.1.0 — grade mensal por horário e tooltip legível */
.month-scheduler{
  width:100%;
  overflow-x:auto;
  position:relative;
  border:1px solid #dbe5ef;
  border-radius:16px;
  background:#fff;
}

.month-scheduler-weekdays{
  display:grid;
  grid-template-columns:repeat(7,minmax(190px,1fr));
  min-width:1330px;
  background:#e8f1fa;
  border-bottom:1px solid #dbe5ef;
}

.month-scheduler-weekdays div{
  padding:10px;
  text-align:center;
  font-weight:900;
  color:#123B63;
}

.month-scheduler-grid{
  display:grid;
  grid-template-columns:repeat(7,minmax(190px,1fr));
  min-width:1330px;
}

.month-day{
  min-height:390px;
  border-right:1px solid #dbe5ef;
  border-bottom:1px solid #dbe5ef;
  position:relative;
  background:#fff;
  cursor:pointer;
}

.month-day.emptyday{
  background:#f8fafc;
}

.month-day-number{
  position:absolute;
  top:8px;
  left:8px;
  z-index:4;
  font-weight:900;
  color:#0f172a;
  font-size:16px;
}

.month-day-hours{
  position:absolute;
  left:0;
  right:0;
  top:34px;
  height:330px;
}

.month-hour-line{
  height:30px;
  border-top:1px solid #f1f5f9;
  position:relative;
}

.month-hour-line span{
  position:absolute;
  right:6px;
  top:2px;
  color:#94a3b8;
  font-size:9px;
  font-weight:800;
}

.month-event{
  position:absolute;
  left:8px;
  right:8px;
  z-index:5;
  border-radius:9px;
  padding:4px 6px;
  color:#fff;
  overflow:hidden;
  box-shadow:0 4px 10px rgba(15,23,42,.14);
  border:1px solid rgba(255,255,255,.25);
}

.month-event strong{
  display:block;
  font-size:11px;
  line-height:1.15;
  white-space:nowrap;
  overflow:hidden;
  text-overflow:ellipsis;
}

.month-event span{
  display:block;
  font-size:10px;
  line-height:1.15;
  white-space:nowrap;
  overflow:hidden;
  text-overflow:ellipsis;
}

.calendar-tooltip-floating{
  white-space:pre-line !important;
  line-height:1.55 !important;
}


/* v3.1.1 — cards da tela inicial clicáveis */
.metrics .metric,
.metric-clickable{
  cursor:pointer;
}


/* v3.1.2 — bloqueios visíveis nos calendários */
.bloqueio-event{
  background:#fff1f2 !important;
  border-color:#fb7185 !important;
  border-left-color:#dc2626 !important;
  color:#7f1d1d !important;
}
.bloqueio-event strong,
.bloqueio-event span{
  color:#7f1d1d !important;
}
.month-event.bloqueio-event{
  border:1px solid #fb7185;
  border-left:5px solid #dc2626;
}
.week-event.bloqueio-event{
  z-index:3;
  opacity:.95;
}
.daily-visit.bloqueio-event{
  border-left:5px solid #dc2626;
}


/* v3.1.3 — correção calendário mensal com sábado visível */
.month-scheduler{
  width:100%;
  overflow-x:auto;
}

.month-scheduler-weekdays,
.month-scheduler-grid{
  display:grid !important;
  grid-template-columns:repeat(7, minmax(170px, 1fr)) !important;
  min-width:1190px !important;
}

.month-day{
  min-width:170px;
  box-sizing:border-box;
}

@media (min-width:1500px){
  .month-scheduler-weekdays,
  .month-scheduler-grid{
    min-width:100% !important;
    grid-template-columns:repeat(7, minmax(0, 1fr)) !important;
  }
}


/* v3.1.4 — evita esconder visitas sobrepostas no calendário */
.month-day-hours{
  height:390px !important;
}

.month-hour-line{
  height:30px !important;
}

.week-scheduler-day{
  height:780px !important;
}

.time-slot-label,
.time-grid-line{
  height:60px !important;
}

.month-event,
.week-event{
  box-sizing:border-box;
  overflow:hidden;
}

.week-event{
  right:auto !important;
}

.month-event{
  right:auto !important;
}

.month-event strong,
.week-event strong{
  white-space:nowrap;
  overflow:hidden;
  text-overflow:ellipsis;
}


/* v3.1.5 — calendário interativo legível sem esconder visitas */
.month-scheduler-list .month-day{
  min-height:520px !important;
}

.month-day-list{
  overflow:hidden;
}

.month-day-agenda{
  position:absolute;
  left:0;
  right:0;
  top:34px;
  bottom:0;
  overflow-y:auto;
}

.month-hour-row{
  min-height:34px;
  display:grid;
  grid-template-columns:24px 1fr;
  border-top:1px solid #eef2f7;
  cursor:pointer;
  padding:2px 3px;
}

.month-hour-row:hover,
.week-list-hour-row:hover{
  background:#f8fafc;
}

.month-hour-label{
  color:#94a3b8;
  font-size:10px;
  font-weight:900;
  padding-top:3px;
}

.month-hour-items{
  display:flex;
  flex-direction:column;
  gap:3px;
  min-width:0;
}

.month-list-event,
.week-list-event{
  background:#f8fafc;
  border:1px solid #dbe5ef;
  border-left:5px solid #1E5A8A;
  border-radius:9px;
  padding:4px 6px;
  box-shadow:0 3px 8px rgba(15,23,42,.08);
  min-width:0;
  cursor:pointer;
}

.month-list-event strong,
.week-list-event strong{
  display:block;
  color:#0f172a;
  font-size:11px;
  line-height:1.15;
  white-space:nowrap;
  overflow:hidden;
  text-overflow:ellipsis;
}

.month-list-event span,
.week-list-event span{
  display:block;
  color:#475569;
  font-size:10px;
  line-height:1.15;
  white-space:nowrap;
  overflow:hidden;
  text-overflow:ellipsis;
}

.week-scheduler-list{
  overflow-x:auto;
}

.week-list-body{
  display:grid;
  grid-template-columns:70px repeat(7,minmax(180px,1fr));
  min-width:1330px;
}

.week-list-time-label{
  min-height:54px;
  border-bottom:1px solid #e5e7eb;
  padding:6px 8px;
  color:#64748b;
  font-weight:900;
  font-size:13px;
  background:#f8fafc;
}

.week-list-day{
  border-left:1px solid #e5e7eb;
}

.week-list-hour-row{
  min-height:54px;
  border-bottom:1px solid #eef2f7;
  padding:3px;
  display:flex;
  flex-direction:column;
  gap:3px;
  cursor:pointer;
}


/* v3.1.6 — grade de 30 em 30 minutos */
.week-list-body{
  grid-template-columns:78px repeat(7,minmax(190px,1fr)) !important;
  min-width:1408px !important;
}

.week-list-time-label{
  min-height:42px !important;
  height:auto !important;
  padding:5px 7px !important;
  font-size:12px !important;
}

.week-list-hour-row{
  min-height:42px !important;
  height:auto !important;
  padding:3px !important;
}

.half-hour-label{
  color:#94a3b8 !important;
  font-size:11px !important;
  background:#fbfdff !important;
}

.half-hour-row{
  border-bottom:1px solid #edf2f7 !important;
}

.week-list-hour-row.half-hour-row{
  background:#fcfdff;
}

.month-day-list{
  min-height:760px !important;
}

.month-hour-row{
  min-height:42px !important;
  grid-template-columns:38px 1fr !important;
}

.month-hour-label{
  font-size:9px !important;
  writing-mode:horizontal-tb;
  color:#64748b !important;
}

.month-hour-row.halfhour-row:nth-child(even){
  background:#fcfdff;
}


/* v3.1.7 — segunda a sábado, 08h às 18h, alinhamento corrigido */
.no-sunday-calendar .month-scheduler-weekdays,
.no-sunday-calendar.month-scheduler .month-scheduler-grid{
  grid-template-columns:repeat(6, minmax(190px, 1fr)) !important;
  min-width:1140px !important;
}

.no-sunday-calendar .week-scheduler-head,
.no-sunday-calendar .week-list-body{
  grid-template-columns:78px repeat(6, minmax(210px, 1fr)) !important;
  min-width:1338px !important;
}

.week-scheduler-head{
  display:grid !important;
  align-items:stretch;
}

.week-list-body{
  display:grid !important;
}

.week-scheduler-day-head{
  box-sizing:border-box;
}

.month-day-list{
  min-height:690px !important;
}

.week-list-time-label,
.week-list-hour-row{
  min-height:44px !important;
}

.month-hour-row{
  min-height:44px !important;
}


/* v3.1.8 — semanal sem recorte, segunda a sábado e linhas com altura automática */
.week-autoheight{
  width:100%;
  overflow-x:visible !important;
}

.week-autoheight .week-scheduler-head{
  display:grid !important;
  grid-template-columns:78px repeat(6, minmax(0, 1fr)) !important;
  min-width:0 !important;
  width:100% !important;
}

.week-table{
  display:grid;
  grid-template-columns:78px repeat(6, minmax(0, 1fr));
  width:100%;
  min-width:0;
  border-left:1px solid #dbe5ef;
  border-top:1px solid #e5e7eb;
}

.week-time-cell{
  background:#f8fafc;
  border-right:1px solid #dbe5ef;
  border-bottom:1px solid #e5e7eb;
  padding:8px 7px;
  color:#64748b;
  font-weight:900;
  font-size:13px;
  box-sizing:border-box;
}

.week-slot-cell{
  border-right:1px solid #e5e7eb;
  border-bottom:1px solid #eef2f7;
  padding:4px;
  box-sizing:border-box;
  display:flex;
  flex-direction:column;
  gap:4px;
  cursor:pointer;
  overflow:visible;
}

.week-slot-cell:hover{
  background:#f8fafc;
}

.week-autoheight .week-list-event{
  width:100%;
  box-sizing:border-box;
  margin:0;
}

.week-autoheight .week-scheduler-day-head{
  min-width:0;
  box-sizing:border-box;
}

.week-autoheight .time-col,
.week-autoheight .week-list-body{
  display:none !important;
}

@media(max-width:1100px){
  .week-autoheight{
    overflow-x:auto !important;
  }

  .week-autoheight .week-scheduler-head,
  .week-table{
    min-width:1180px !important;
    grid-template-columns:78px repeat(6, 184px) !important;
  }
}


/* v3.1.9 — status reserva cancelada */
.status.reserva_cancelada{
  background:#f1f5f9;
  color:#475569;
}


/* v3.2.1 — análise de cancelamentos com Outros detalhado */
