  padding:6px 9px;
  border-radius:8px;
  background:rgba(255,255,255,.12);
  font-size:13px;
}

.owner-correction-admin{
  color:#7c3aed !important;
  font-weight:800;
}

.owner-audit-box{
  margin-top:12px;
  padding:12px;
  border:1px solid #dbe4ee;
  border-radius:10px;
  background:#f8fafc;
  display:flex;
  flex-direction:column;
  gap:5px;
  color:#475569;
  font-size:12px;
}

.owner-audit-box strong{
  color:#123B63;
  font-size:13px;
}

.owner-hash{
  font-family:ui-monospace,SFMono-Regular,Menlo,Consolas,monospace;
  word-break:break-all;
}


/* v3.5.4 — filtros das fichas de proprietários */
.owner-admin-filters{
  display:grid;
  grid-template-columns:minmax(260px,2fr) minmax(160px,1fr) minmax(160px,1fr) auto;
  gap:10px;
  align-items:end;
  margin:14px 0;
  padding:14px;
  border:1px solid #dbe4ee;
  border-radius:14px;
  background:#f8fafc;
}

.owner-admin-filters label{
  display:flex;
  flex-direction:column;
  gap:6px;
}

.owner-admin-filters label span{
  color:#334155;
  font-weight:800;
  font-size:13px;
}

.owner-admin-filters input{
  min-height:42px;
  border:1px solid #cbd5e1;
  border-radius:10px;
  padding:8px 10px;
  background:#fff;
}

@media(max-width:900px){
  .owner-admin-filters{
    grid-template-columns:1fr 1fr;
  }
}

@media(max-width:620px){
  .owner-admin-filters{
    grid-template-columns:1fr;
  }

  .owner-admin-filters .btn{
    width:100%;
  }
}


/* v3.5.5 — confirmação pública de visita via link do WhatsApp */
.confirmacao-publica-shell{
  min-height:100vh;
  display:flex;
  align-items:center;
  justify-content:center;
  padding:24px 16px;
  background:#f3f6fa;
  color:#123B63;
}

.confirmacao-publica-card{
  width:min(100%,560px);
  background:#fff;
  border-radius:22px;
  padding:28px;
  box-shadow:0 18px 45px rgba(15,41,66,.14);
  text-align:center;
}

.confirmacao-brand{
  font-size:13px;
  font-weight:1000;
  letter-spacing:1.5px;
  color:#B91C1C;
  margin-bottom:18px;
}

.confirmacao-publica-card h1{
  margin:0 0 12px;
  color:#123B63;
}

.confirmacao-publica-card h2{
  color:#123B63;
}

.confirmacao-intro{
  font-size:17px;
  line-height:1.5;
  color:#475569;
}

.confirmacao-question{
  font-size:19px;
  font-weight:900;
  color:#123B63;
  margin:18px 0;
}

.confirmacao-detalhes{
  display:flex;
  flex-direction:column;
  gap:5px;
  padding:15px;
  border:1px solid #dbe4ee;
  border-radius:14px;
  background:#f8fafc;
  margin:18px 0;
  color:#475569;
}

.confirmacao-detalhes strong{
  color:#123B63;
  font-size:18px;
}

.confirmacao-actions{
  display:grid;
  grid-template-columns:1fr 1fr;
  gap:10px;
  margin-top:16px;
}

.confirmacao-btn{
  min-height:50px;
  border:0;
  border-radius:13px;
  padding:11px 15px;
  font-size:15px;
  font-weight:900;
  cursor:pointer;
}

.confirmacao-btn:disabled{
  opacity:.55;
  cursor:not-allowed;
}

.confirmacao-btn.confirmar{
  background:#15803d;
  color:#fff;
}

.confirmacao-btn.cancelar{
  background:#b91c1c;
  color:#fff;
}

.confirmacao-btn.voltar{
  background:#e2e8f0;
  color:#334155;
}

.confirmacao-cancel-box{
  margin-top:18px;
  text-align:left;
  padding:15px;
  border:1px solid #fecdd3;
  background:#fff7f7;
  border-radius:14px;
}

.confirmacao-cancel-box label{
  display:flex;
  flex-direction:column;
  gap:7px;
  font-weight:800;
}

.confirmacao-cancel-box textarea{
  min-height:100px;
  resize:vertical;
  border:1px solid #cbd5e1;
  border-radius:10px;
  padding:10px;
  font:inherit;
}

.confirmacao-icon{
  width:64px;
  height:64px;
  border-radius:50%;
  margin:0 auto 16px;
  display:flex;
  align-items:center;
  justify-content:center;
  font-size:38px;
  font-weight:900;
}

.confirmacao-publica-card.success .confirmacao-icon{
  background:#dcfce7;
  color:#15803d;
}

.confirmacao-publica-card.cancelled .confirmacao-icon{
  background:#fee2e2;
  color:#b91c1c;
}

@media(max-width:560px){
  .confirmacao-publica-shell{
    padding:0;
    align-items:stretch;
  }

  .confirmacao-publica-card{
    border-radius:0;
    min-height:100vh;
    padding:24px 18px;
    display:flex;
    flex-direction:column;
    justify-content:center;
  }

  .confirmacao-actions{
    grid-template-columns:1fr;
  }
}

/* v3.5.6 — complemento do imóvel */
.form input::placeholder{color:#94a3b8;}


/* v3.5.7 — botão de ativação Web Push */
.header-actions button{
  transition:transform .12s ease, opacity .12s ease;
}


/* v3.5.11 — WhatsApp do proprietário */
.toast-whatsapp-owner,
.notification-whatsapp-owner{
  display:inline-flex;
  align-items:center;
  justify-content:center;
  width:max-content;
  margin-top:8px;
  padding:8px 11px;
  border-radius:9px;
  background:#15803d;
  color:#fff !important;
  text-decoration:none;
  font-weight:900;
  font-size:13px;
}
.toast-whatsapp-owner:hover,
.notification-whatsapp-owner:hover{filter:brightness(.95);}
.notification-item .notification-whatsapp-owner{margin-bottom:8px;}


/* v3.5.14 — administrador superusuário operacional */
.bloqueio-actions{
  display:flex;
  gap:8px;
  flex-wrap:wrap;
  margin-top:8px;
}

.bloqueio-form select{
  min-height:42px;
  border:1px solid #cbd5e1;
  border-radius:10px;
  padding:8px 10px;
  background:#fff;
}
